@app.post("/integrations/sync")
def sync_external_integration(
    integration_id: str = Body(..., embed=True),
    user: User = Depends(get_current_user),
    db: Session = Depends(get_db)
):
    integration = db.query(Integration).filter(
        Integration.id == integration_id,
        Integration.organization_id == user.organization_id
    ).first()
    if not integration:
        raise HTTPException(status_code=404, detail="Integration not found")

    sync_external_crm.delay(integration_id)
    return {"status": "sync_dispatched", "integration_id": integration_id}
